let activeCategory = "Tutti";
let cart = JSON.parse(localStorage.getItem("cruci-cart") || "[]");
const grid = document.querySelector("#product-grid");
const filters = document.querySelector("#filters");
const search = document.querySelector("#search");
const cartEl = document.querySelector("#cart");
const overlay = document.querySelector("#overlay");

function renderFilters() { ["Tutti", ...new Set(products.map(p => p.category))].forEach(category => { const button = document.createElement("button"); button.className = `filter ${category === activeCategory ? "active" : ""}`; button.textContent = category; button.onclick = () => { activeCategory = category; renderFilters(); renderProducts(); }; filters.append(button); }); }
function formatPrice(product) { return product.price === null ? "Prezzo su richiesta" : new Intl.NumberFormat("it-IT", { style: "currency", currency: "EUR" }).format(product.price); }
function renderProducts() { const term = search.value.toLowerCase(); grid.innerHTML = products.filter(p => (activeCategory === "Tutti" || p.category === activeCategory) && `${p.name} ${p.category} ${p.description}`.toLowerCase().includes(term)).map(p => `<article class="product-card"><div class="product-image" data-detail="${p.id}"><img src="${p.image}" alt="${p.name}" loading="lazy" />${p.tag ? `<span class="tag">${p.tag}</span>` : ""}</div><div class="product-meta"><span class="product-category">${p.category}</span><h3 class="product-name" data-detail="${p.id}">${p.name}</h3><div class="product-bottom"><span><strong class="product-price">${formatPrice(p)}</strong><br><small class="availability">${p.available ? "Disponibile" : "Non disponibile"}</small></span><button class="add" data-id="${p.id}">Aggiungi</button></div></div></article>`).join("") || "<p>Nessun prodotto trovato.</p>"; document.querySelectorAll(".add").forEach(button => button.onclick = () => addToCart(Number(button.dataset.id))); document.querySelectorAll("[data-detail]").forEach(element => element.onclick = () => openDetail(Number(element.dataset.detail))); }
function addToCart(id) { const current = cart.find(item => item.id === id); current ? current.quantity++ : cart.push({ id, quantity: 1 }); saveCart(); openCart(); }
function saveCart() { localStorage.setItem("cruci-cart", JSON.stringify(cart)); document.querySelector("#cart-count").textContent = cart.reduce((total, item) => total + item.quantity, 0); renderCart(); }
function renderCart() { const holder = document.querySelector("#cart-items"); const totalBox = document.querySelector("#cart-total"); holder.innerHTML = cart.length ? cart.map(item => { const product = products.find(p => p.id === item.id); return `<div class="cart-row"><img src="${product.image}" alt="" /><div><strong>${product.name}</strong><br /><small>Quantità: ${item.quantity} · ${formatPrice(product)}</small></div><button aria-label="Rimuovi ${product.name}" data-remove="${item.id}">×</button></div>`; }).join("") : '<p class="empty">La tua borsa è vuota.</p>'; document.querySelectorAll("[data-remove]").forEach(button => button.onclick = () => { cart = cart.filter(item => item.id !== Number(button.dataset.remove)); saveCart(); }); const unknownPrice = cart.some(item => products.find(product => product.id === item.id).price === null); const total = cart.reduce((sum, item) => { const price = products.find(product => product.id === item.id).price; return sum + (price === null ? 0 : price * item.quantity); }, 0); totalBox.hidden = !cart.length; totalBox.innerHTML = `<span>Totale${unknownPrice ? '<small>Alcuni prezzi sono da confermare</small>' : ''}</span><strong>${formatPrice({ price: total })}${unknownPrice ? '+' : ''}</strong>`; const lines = cart.map(item => { const p = products.find(product => product.id === item.id); return `• ${p.name} × ${item.quantity} — ${formatPrice(p)}`; }).join("\n"); const totalLine = unknownPrice ? `Totale parziale: ${formatPrice({ price: total })}\n(da confermare per gli articoli senza prezzo)` : `Totale: ${formatPrice({ price: total })}`; document.querySelector("#whatsapp-order").href = `https://wa.me/393793397079?text=${encodeURIComponent("Ciao, vorrei ordinare:\n" + lines + "\n\n" + totalLine)}`; }
function openDetail(id) { const product = products.find(item => item.id === id); const images = product.images?.length ? product.images : [product.image]; document.querySelector("#product-detail").innerHTML = `<div class="detail"><div><div class="detail-image"><img id="detail-main-image" src="${images[0]}" alt="${product.name}" /></div>${images.length > 1 ? `<div class="detail-thumbnails">${images.map((image, index) => `<button class="detail-thumb ${index === 0 ? "active" : ""}" data-image="${image}" aria-label="Foto ${index + 1} di ${product.name}"><img src="${image}" alt="" /></button>`).join("")}</div>` : ""}</div><div class="detail-copy"><p class="eyebrow">${product.category}</p><h2>${product.name}</h2><p class="detail-description">${product.description}</p><div class="detail-info"><span class="availability">${product.available ? "Disponibile" : "Non disponibile"}</span><strong class="detail-price">${formatPrice(product)}</strong></div><button class="button" id="detail-add" ${product.available ? "" : "disabled"}>Aggiungi alla borsa</button></div></div>`; const dialog = document.querySelector("#product-dialog"); dialog.showModal(); document.querySelectorAll(".detail-thumb").forEach(button => button.onclick = () => { document.querySelector("#detail-main-image").src = button.dataset.image; document.querySelectorAll(".detail-thumb").forEach(item => item.classList.toggle("active", item === button)); }); document.querySelector("#detail-add").onclick = () => { addToCart(id); dialog.close(); }; }
function openCart() { cartEl.classList.add("open"); overlay.classList.add("open"); cartEl.setAttribute("aria-hidden", "false"); }
function closeCart() { cartEl.classList.remove("open"); overlay.classList.remove("open"); cartEl.setAttribute("aria-hidden", "true"); }
document.querySelector("#cart-toggle").onclick = openCart; document.querySelector("#cart-close").onclick = closeCart; document.querySelector("#dialog-close").onclick = () => document.querySelector("#product-dialog").close(); overlay.onclick = closeCart; search.oninput = renderProducts; document.querySelector("#year").textContent = new Date().getFullYear(); renderFilters(); renderProducts(); saveCart();
